import { test, expect } from '@playwright/test';

test.describe('Auto-Save Form Draft Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should auto-save form as draft every 30 seconds', async ({ page }) => {
    // Verify initial form state
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toBeVisible();
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    const messageInput = page.getByLabel('Message');
    await expect(messageInput).toBeVisible();

    // Fill in form fields
    await nameInput.fill('John Doe');
    await emailInput.fill('john.doe@example.com');
    await messageInput.fill('This is a test message');

    // Verify initial save state
    const saveButton = page.getByRole('button', { name: /save draft/i });
    await expect(saveButton).toBeVisible();
    await expect(saveButton).toBeDisabled();

    // Wait for auto-save interval
    await page.waitForTimeout(30000);

    // Verify draft is saved
    const draftId = page.getByText('Draft saved');
    await expect(draftId).toBeVisible();

    // Verify save button is now enabled
    await expect(saveButton).toBeEnabled();

    // Click save button to confirm draft
    await saveButton.click();

    // Verify success message
    const successMessage = page.getByText('Form saved as draft');
    await expect(successMessage).toBeVisible();

    // Verify form fields are still visible
    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(messageInput).toBeVisible();

    // Verify draft ID is displayed
    await expect(draftId).toBeVisible();
  });

  test('should not auto-save when form is empty', async ({ page }) => {
    // Verify initial form state
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toBeVisible();
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    const messageInput = page.getByLabel('Message');
    await expect(messageInput).toBeVisible();

    // Verify save button is disabled initially
    const saveButton = page.getByRole('button', { name: /save draft/i });
    await expect(saveButton).toBeDisabled();

    // Wait for auto-save interval
    await page.waitForTimeout(30000);

    // Verify save button is still disabled
    await expect(saveButton).toBeDisabled();

    // Verify no draft is saved
    const draftId = page.getByText('Draft saved');
    await expect(draftId).not.toBeVisible();

    // Verify success message is not displayed
    const successMessage = page.getByText('Form saved as draft');
    await expect(successMessage).not.toBeVisible();

    // Verify form fields are still visible
    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(messageInput).toBeVisible();
  });
});
